/**
 * Writes scripts/data/nupco-tender-market-research-saudi-arabia.json with every Sanity
 * blogPost field filled from the hardcoded SSR module.
 *
 * Cover / hero JPEGs are generated by scripts/generate-nupco-tender-research-cover.mjs.
 *
 *   node scripts/generate-nupco-tender-research-sanity-json.mjs
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { createServer } from 'vite';

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..');
const outPath = path.join(root, 'scripts/data/nupco-tender-market-research-saudi-arabia.json');

export const SARAH_CHEN_SANITY_ID = '498ba300-bfab-4a76-b256-b2139d4d66fe';

/** Every blogPost field that applies to a healthcare-silo article. */
export const NUPCO_TENDER_SANITY_FIELDS = [
  'seo',
  'openGraph',
  'title',
  'slug',
  'excerpt',
  'publishedAt',
  'updatedAt',
  'author',
  'mainImage',
  'categories',
  'category',
  'contentSilo',
  'tags',
  'country',
  'language',
  'readingTime',
  'executiveSummary',
  'tableOfContents',
  'bodyHtml',
  'body',
  'faq',
  'relatedPostSlugs',
  'ctaSection',
  'sources',
  'factCheckedAt',
];

function stripHtml(html) {
  return String(html)
    .replace(/<[^>]+>/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&#x27;|&#39;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/&nbsp;/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function portableText(text) {
  return {
    _type: 'block',
    style: 'normal',
    children: [{ _type: 'span', marks: [], text }],
    markDefs: [],
  };
}

function extractSources(bodyHtml) {
  return [...bodyHtml.matchAll(/<li id="ref-[^"]+">([\s\S]*?)<\/li>/g)].map((match) =>
    stripHtml(match[1]),
  );
}

async function loadArticle() {
  const vite = await createServer({
    root,
    server: { middlewareMode: true },
    appType: 'custom',
    logLevel: 'error',
  });
  try {
    return await vite.ssrLoadModule('/src/data/blog-nupco-tender-market-research-saudi-arabia.ts');
  } finally {
    await vite.close();
  }
}

export function buildSanityPayload(mod) {
  const shortAnswer = stripHtml(mod.NUPCO_TENDER_EXECUTIVE_SUMMARY_HTML).replace(
    /^Short answer:\s*/i,
    '',
  );
  const firstParagraph = stripHtml(mod.NUPCO_TENDER_BODY_HTML.split('<h2')[0])
    .replace(/^NUPCO tender market research[\s\S]*?This briefing uses only published sources\./, '')
    .trim();

  return {
    seo: {
      metaTitle: mod.NUPCO_TENDER_META_TITLE,
      metaDescription: mod.NUPCO_TENDER_META_DESCRIPTION,
      focusKeyword: 'NUPCO tender market research',
      keywords: [
        'NUPCO tender market research',
        'NUPCO tenders Saudi Arabia',
        'NPT0047/25',
        'Saudi oncology tender',
        'iNUPCO marketplace',
        'NUPCO award rank',
        'specialty medicines Saudi Arabia',
        'SFDA NUPCO',
      ],
      canonicalUrl: mod.NUPCO_TENDER_URL,
      noIndex: false,
    },
    openGraph: {
      ogTitle: mod.NUPCO_TENDER_META_TITLE,
      ogDescription: mod.NUPCO_TENDER_META_DESCRIPTION,
      ogImage: {
        path: `public${mod.NUPCO_TENDER_COVER_IMAGE}`,
        alt: mod.NUPCO_TENDER_COVER_IMAGE_ALT,
        geminiPending: false,
      },
    },
    title: mod.NUPCO_TENDER_DISPLAY_TITLE,
    slug: { _type: 'slug', current: mod.NUPCO_TENDER_SLUG },
    excerpt: mod.NUPCO_TENDER_EXCERPT,
    publishedAt: mod.NUPCO_TENDER_PUBLISHED_ISO,
    updatedAt: mod.NUPCO_TENDER_UPDATED_ISO,
    author: {
      _type: 'reference',
      _ref: SARAH_CHEN_SANITY_ID,
      name: 'Sarah Chen',
      jobTitle: 'Global Research Manager',
    },
    mainImage: {
      path: `public${mod.NUPCO_TENDER_HERO_IMAGE}`,
      alt: mod.NUPCO_TENDER_HERO_IMAGE_ALT,
      caption: 'BioNixus-branded hero for NUPCO tender market research in Saudi Arabia',
      geminiPending: false,
    },
    categories: [{ title: 'Healthcare Market Research' }],
    category: 'Healthcare Market Research',
    contentSilo: 'healthcare',
    tags: [...mod.NUPCO_TENDER_TAGS],
    country: 'Saudi Arabia',
    language: 'en',
    readingTime: mod.NUPCO_TENDER_READING_TIME,
    executiveSummary: [portableText(shortAnswer)],
    tableOfContents: mod.NUPCO_TENDER_TABLE_OF_CONTENTS.map((item) => ({
      heading: item.heading,
      anchor: item.anchor,
    })),
    bodyHtml: `${mod.NUPCO_TENDER_EXECUTIVE_SUMMARY_HTML}\n\n${mod.NUPCO_TENDER_BODY_HTML}`,
    body: [
      {
        _type: 'callout',
        type: 'insight',
        title: 'Short answer',
        content: shortAnswer,
      },
      {
        _type: 'dataVisualization',
        title: 'What NUPCO tender market research should measure',
        type: 'table',
        data: JSON.stringify(
          mod.NUPCO_TENDER_WORKSTREAMS.map((stream) => ({
            name: stream.name,
            researchType: stream.researchType,
            question: stream.question,
          })),
        ),
        source: 'NUPCO NPT0047/25; NPT0050-25 Phase 2; Saudi Cancer Registry 2024; GASTAT 2024; PPRI 2024',
      },
      portableText(
        firstParagraph ||
          'NUPCO tender market research is a bid-evidence problem before it is a procurement-process problem.',
      ),
    ],
    faq: mod.NUPCO_TENDER_FAQ.map((item) => ({
      question: item.question,
      answer: item.answer,
    })),
    relatedPostSlugs: [
      'hematology-market-research-saudi-arabia',
      'how-to-choose-healthcare-market-research-agency-saudi-arabia',
      'gcc-pharmacoeconomics',
    ],
    ctaSection: { ...mod.NUPCO_TENDER_HARDCODED_POST.ctaSection },
    sources: extractSources(mod.NUPCO_TENDER_BODY_HTML),
    factCheckedAt: mod.NUPCO_TENDER_UPDATED_ISO,
    geminiCoverPending: false,
    coverNote:
      'mainImage and openGraph.ogImage are the Playwright-rendered BioNixus JPEGs at public/images/blog/nupco-tender-market-research-saudi-arabia-{hero,cover}.jpg.',
  };
}

async function main() {
  const mod = await loadArticle();
  const payload = buildSanityPayload(mod);
  for (const field of NUPCO_TENDER_SANITY_FIELDS) {
    if (payload[field] == null) {
      throw new Error(`Sanity payload missing field: ${field}`);
    }
  }
  fs.mkdirSync(path.dirname(outPath), { recursive: true });
  fs.writeFileSync(outPath, `${JSON.stringify(payload, null, 2)}\n`);
  console.log(`Wrote ${path.relative(root, outPath)} (${payload.sources.length} sources, bodyHtml ${payload.bodyHtml.length} chars)`);
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  main().catch((error) => {
    console.error(error);
    process.exit(1);
  });
}
